package org.apache.commons.lang.enums;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ClassUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen2Test {

    // Concrete implementation of ValuedEnum for testing purposes
    private enum TestEnum implements ValuedEnum {
        INSTANCE_1("INSTANCE_1", 1),
        INSTANCE_2("INSTANCE_2", 2),
        INSTANCE_3("INSTANCE_3", 3);

        private final String name;
        private final int iValue;

        TestEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    // Another enum to test ClassCastException
    private enum DifferentEnum implements ValuedEnum {
        OTHER("OTHER", 1);

        private final String name;
        private final int iValue;

        DifferentEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    @Test
    public void testCompareTo_SameInstance() {
        // if (other == this) return 1;
        TestEnum instance = TestEnum.INSTANCE_1;
        assertEquals(1, instance.compareTo(instance));
    }

    @Test
    public void testCompareTo_SameClass_DifferentValue() {
        // return iValue - ((ValuedEnum) other).iValue;
        // Case: 1 - 2 = -1
        assertEquals(-1, TestEnum.INSTANCE_1.compareTo(TestEnum.INSTANCE_2));
        // Case: 2 - 1 = 1
        assertEquals(1, TestEnum.INSTANCE_2.compareTo(TestEnum.INSTANCE_1));
        // Case: 2 - 2 = 0
        assertEquals(0, TestEnum.INSTANCE_2.compareTo(TestEnum.INSTANCE_2));
    }

    @Test(expected = ClassCastException.class)
    public void testCompareTo_DifferentClass() {
        // throw new ClassCastException(...)
        TestEnum instance = TestEnum.INSTANCE_1;
        instance.compareTo(DifferentEnum.OTHER);
    }

    /**
     * Note: The branch `if (other.getClass().getName().equals(this.getClass().getName()))` 
     * inside the `if (other.getClass() != this.getClass())` block is theoretically 
     * impossible to reach in a standard JVM environment because if the class names 
     * are equal, the classes themselves are equal (unless dealing with complex 
     * custom ClassLoader hierarchies where the same class name exists in different loaders).
     * 
     * However, to satisfy coverage requirements for the logic provided:
     * The current implementation of the method has a logical redundancy:
     * if (other.getClass() != this.getClass()) {
     *    if (other.getClass().getName().equals(this.getClass().getName())) { ... }
     * }
     * 
     * In standard JUnit tests, the second 'if' is unreachable because 
     * 'getClass() != getClass()' implies 'getName() != getName()'.
     */
}
